def born(a, b):
    t = a * a + b * b
    return [round(a * a / t, 4), round(b * b / t, 4)]

def apply_h(s):
    r = 0.70710678
    return [round(r * (s[0] + s[1]), 4), round(r * (s[0] - s[1]), 4)]

